-- PT112-S1-Q17. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT112-S1-Q17$batch12$ AND q.stimulus=$batch12$The best way to write a good detective story is to work backward from the crime. The writer should first decide what the crime is and who the perpetrator is, and then come up with the circumstances and clues based on those decisions.$batch12$ AND q.prompt=$batch12$Which one of the following illustrates a principle most similar to that illustrated by the passage?$batch12$ AND q.correct_choice=$batch12$E$batch12$) THEN RAISE EXCEPTION 'Question changed: PT112-S1-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT112-S1-Q17$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S1-Q17'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT112-S1-Q17$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The best way to write a detective story is to work backward from the crime.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Decide the crime and the culprit first, then build the circumstances and clues from those choices.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$The principle: decide the end result first, then work out the steps that lead to it.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Fix the outcome first, then plan backward to get there.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT112-S1-Q17$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Most people plan finances before picking a destination. That's planning forward.$batch12$), ($batch12$B$batch12$, $batch12$Prepare the soil, then choose what to plant. Forward again.$batch12$), ($batch12$C$batch12$, $batch12$This links design to construction method. No working backward.$batch12$), ($batch12$D$batch12$, $batch12$Try many strategies. That's trial and error, not working back from a goal.$batch12$), ($batch12$E$batch12$, $batch12$Picture where the shot should land, then figure out the position needed. Same principle.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT112-S1-Q17$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
